{
  "core_question": "How should a US-based clinical-stage biotech structure and value a co-development and co-commercialization deal with an EU pharma for a single Phase 3 oncology asset, considering clinical risk, regulatory/IP exposure, and financial economics?",
  "rationale": "The question spans clinical program risk and regulatory pathways (healthcare), territorial rights, IP ownership, and milestone enforceability across jurisdictions (legal), and requires valuation of upfront/milestone payments, royalties, and rNPV analysis (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Identify the primary clinical and regulatory risks for a single Phase 3 oncology asset seeking FDA accelerated approval, quantify how these risks impact milestone timing and payment levels, and recommend mitigation strategies that can be incorporated into a co-development agreement.",
    "legal": "Explain how US versus EU/UK territorial rights should be allocated in a co-development deal for an oncology asset, detailing IP ownership, regulatory approval responsibilities, and enforceability of milestone payments under current US, EU, and UK law, including any implications of accelerated approval pathways.",
    "finance": "Outline the valuation methodology—including rNPV calculation—for a pre-revenue biotech with one Phase 3 oncology asset, showing how upfront payments, milestone structures, tiered royalties, and territorial splits affect net present value and risk-adjusted returns."
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Potentially stale FDA accelerated approval guidance (post-2024), EMA/UK MHRA regulatory updates post-Brexit, recent EU patent law changes, and current biotech valuation trends."
}
